ALTER TABLE visitor_decisions DROP CONSTRAINT IF EXISTS visitor_decisions_decision_type_check;
ALTER TABLE visitor_decisions ADD CONSTRAINT visitor_decisions_decision_type_check CHECK (decision_type IN ('clarify_intent','present_offering','request_qualification','request_contact','request_time_window','offer_next_step','no_safe_decision'));
CREATE TABLE IF NOT EXISTS visitor_contact_records (id uuid PRIMARY KEY, organization_id uuid NOT NULL, business_id uuid NOT NULL, visitor_identity_id uuid NOT NULL, session_id uuid NOT NULL, name text, email text, phone text, preferred_channel text CHECK (preferred_channel IN ('email','phone')), source_observation_id uuid NOT NULL, idempotency_key text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (organization_id,business_id,id), UNIQUE (organization_id,visitor_identity_id,idempotency_key), FOREIGN KEY (organization_id,business_id,visitor_identity_id) REFERENCES visitor_identities(organization_id,business_id,id) ON DELETE CASCADE, FOREIGN KEY (organization_id,business_id,session_id) REFERENCES visitor_sessions(organization_id,business_id,id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS visitor_consents (id uuid PRIMARY KEY, organization_id uuid NOT NULL, business_id uuid NOT NULL, visitor_identity_id uuid NOT NULL, session_id uuid NOT NULL, purpose text NOT NULL, version text NOT NULL, status text NOT NULL CHECK (status IN ('granted','withdrawn')), source_observation_id uuid NOT NULL, idempotency_key text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (organization_id,business_id,id), UNIQUE (organization_id,visitor_identity_id,idempotency_key), FOREIGN KEY (organization_id,business_id,visitor_identity_id) REFERENCES visitor_identities(organization_id,business_id,id) ON DELETE CASCADE, FOREIGN KEY (organization_id,business_id,session_id) REFERENCES visitor_sessions(organization_id,business_id,id) ON DELETE CASCADE);
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['visitor_contact_records','visitor_consents'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t); EXECUTE format('CREATE POLICY %I ON %I USING (organization_id = kablet_current_org() AND business_id = kablet_current_business()) WITH CHECK (organization_id = kablet_current_org() AND business_id = kablet_current_business())',t||'_isolation',t); END LOOP; END $$;
GRANT SELECT, INSERT ON visitor_contact_records, visitor_consents TO kablet_dev;
GRANT SELECT, DELETE ON visitor_contact_records, visitor_consents TO kablet_privacy_owner;
SET LOCAL ROLE kablet_privacy_owner;
GRANT EXECUTE ON FUNCTION kablet_visitor_immutable() TO kablet_test_bootstrap;
RESET ROLE;
CREATE TRIGGER visitor_contact_records_immutable BEFORE UPDATE OR DELETE ON visitor_contact_records FOR EACH ROW EXECUTE FUNCTION kablet_visitor_immutable();
CREATE TRIGGER visitor_consents_immutable BEFORE UPDATE OR DELETE ON visitor_consents FOR EACH ROW EXECUTE FUNCTION kablet_visitor_immutable();
SET LOCAL ROLE kablet_privacy_owner;
REVOKE EXECUTE ON FUNCTION kablet_visitor_immutable() FROM kablet_test_bootstrap;
RESET ROLE;
SET LOCAL ROLE kablet_privacy_owner;
CREATE OR REPLACE FUNCTION kablet_visitor_privacy_delete(p_organization_id uuid, p_visitor_id uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public AS $$ DECLARE deleted boolean; BEGIN IF p_organization_id <> public.kablet_current_org() THEN RAISE EXCEPTION 'privacy tenant mismatch'; END IF; INSERT INTO public.kablet_privacy_operations(transaction_id,organization_id,visitor_identity_id) VALUES (pg_catalog.txid_current(),p_organization_id,p_visitor_id); DELETE FROM public.visitor_decision_business_truth_refs r USING public.visitor_decisions d WHERE d.id=r.decision_id AND d.organization_id=p_organization_id AND d.visitor_identity_id=p_visitor_id; DELETE FROM public.visitor_decisions WHERE organization_id=p_organization_id AND visitor_identity_id=p_visitor_id; DELETE FROM public.visitor_consents WHERE organization_id=p_organization_id AND visitor_identity_id=p_visitor_id; DELETE FROM public.visitor_contact_records WHERE organization_id=p_organization_id AND visitor_identity_id=p_visitor_id; DELETE FROM public.visitor_states WHERE organization_id=p_organization_id AND visitor_identity_id=p_visitor_id; DELETE FROM public.visitor_observations WHERE organization_id=p_organization_id AND visitor_identity_id=p_visitor_id; DELETE FROM public.visitor_state_revisions WHERE organization_id=p_organization_id AND visitor_identity_id=p_visitor_id; DELETE FROM public.visitor_sessions WHERE organization_id=p_organization_id AND visitor_identity_id=p_visitor_id; DELETE FROM public.visitor_identities WHERE organization_id=p_organization_id AND id=p_visitor_id RETURNING true INTO deleted; DELETE FROM public.kablet_privacy_operations WHERE transaction_id=pg_catalog.txid_current() AND organization_id=p_organization_id AND visitor_identity_id=p_visitor_id; RETURN COALESCE(deleted,false); END $$;
RESET ROLE;
